"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3917],{56888:e=>{e.exports=JSON.parse('{"functions":[{"name":"RevealRole","desc":"Sends `player` the role reveal splash (`ROUND_ROLE`) for `role`. The\\npicture is the render of the skin their weapon will wear, falling back to\\nthe plain weapon when the skin has no render. A promoted player already\\nholds their pistol, so their reveal has no countdown chip.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"role","desc":"\\"Murderer\\" | \\"Sheriff\\" | \\"Innocent\\"","lua_type":"string"},{"name":"caption","desc":"The line above the role name","lua_type":"string"},{"name":"partners","desc":"Display names of the others with the role","lua_type":"{ string }?"},{"name":"promoted","desc":"Mid-round promotion","lua_type":"boolean?"}],"returns":[],"function_type":"method","source":{"line":157,"path":"src/Server/Features/Minigames/GameModes/MurderEscape.luau"}}],"properties":[],"types":[],"name":"MurderEscape","desc":"The flagship game mode. One or two players are Murderers, one or two are\\nSheriffs, everyone else is Innocent.\\n\\n- Murderers get a knife after a grace period and must kill everyone.\\n- Sheriffs get a pistol and must kill the murderers.\\n- A Sheriff who kills an Innocent is executed and drops their pistol.\\n- A dropped pistol can only be picked up by an Innocent, who is then\\n  promoted to Sheriff.","source":{"line":16,"path":"src/Server/Features/Minigames/GameModes/MurderEscape.luau"}}')}}]);